'use strict';
const M=window.OpsModel, STORAGE='player-signal-demo-v1';
let state=M.seed(),storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved?.version===1&&Array.isArray(saved.feedback)&&Array.isArray(saved.tickets)&&Array.isArray(saved.demands)&&Array.isArray(saved.kbEnabled))state=saved;}catch{storageOK=false;}
let current='overview',filter={query:'',source:'全部来源',group:'all',ticket:'全部'},lastAnswer=null,toastTimer;
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',signal:'M3 12h4l3-8 4 16 3-8h4',ticket:'M5 4h14v16H5z M8 8h8 M8 12h6 M8 16h4',ai:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',board:'M4 4h16v16H4z M9 4v16 M15 4v16 M6 8h1 M11 12h2 M17 8h1',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M18 8a3 3 0 0 1 0 6 M22 21v-2a4 4 0 0 0-3-4 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',arrow:'M5 12h14 M13 6l6 6-6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',plus:'M12 5v14 M5 12h14',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',check:'M5 12l4 4L19 6',chat:'M4 4h16v12H9l-5 4z',refresh:'M20 6v5h-5 M4 18v-5h5 M5 8a8 8 0 0 1 14-3l1 3 M4 16l1 3a8 8 0 0 0 14-3',link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0 M16 8l2-2a4 4 0 0 0-5-5',calendar:'M4 5h16v16H4z M4 10h16 M8 2v5 M16 2v5'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.signal}"/></svg>`;
const tag=(text,color='')=>`<span class="tag ${color}">${escape(text)}</span>`;
const priority=p=>tag(p,p==='P0'?'red':p==='P1'?'amber':'blue');
const button=(label,action,ico='',cls='',data='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${data}>${ico?icon(ico):''}${label}</button>`;
const textButton=(label,action,data='')=>`<button type="button" class="text-button" data-action="${action}" ${data}>${label}</button>`;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{storageOK=false;toast('浏览器存储不可用，本次操作在当前页面仍然有效');}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
const pages=[['overview','运营总览','overview'],['intelligence','情报中心','signal'],['tickets','客服工作台','ticket'],['ai','AI 客服实验室','ai'],['demands','体验优化看板','board'],['team','外包团队与质检','team']];
function navigate(page){if(!pages.some(p=>p[0]===page))page='overview';current=page;if(location.hash.slice(1)!==page)history.replaceState(null,'','#'+page);render();window.scrollTo({top:0});}
function render(){const m=M.metrics(state);document.getElementById('navigation').innerHTML=pages.map(([id,label,ico],i)=>`${i===5?'<div class="nav-divider"></div>':''}<button title="${label}" class="nav-link ${current===id?'active':''}" data-action="nav" data-page="${id}" ${current===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-text">${label}</span>${id==='tickets'?`<span class="nav-count">${m.open}</span>`:id==='intelligence'?`<span class="nav-count">${m.feedback}</span>`:''}</button>`).join('');document.getElementById('breadcrumb').textContent=pages.find(p=>p[0]===current)[1];app.innerHTML='<div class="page">'+({overview:overview,intelligence:intelligence,tickets:tickets,ai:ai,demands:demands,team:team}[current])()+'</div>';}
function heading(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="page-head-actions">${actions}</div></div>`;}
function metric(label,value,unit,foot,ico){return `<article class="metric"><div class="metric-top">${label}<span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></article>`;}
function panel(title,body,action='',subtitle='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;}
function trend(){return `<div class="panel-body"><svg class="chart" viewBox="0 0 570 195" role="img" aria-label="虚构历史趋势：9月14日反馈48条，其中登录相关22条；独立示例序列，并非下方24条样本汇总"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#5ecdb3" stop-opacity=".22"/><stop offset="1" stop-color="#5ecdb3" stop-opacity="0"/></linearGradient></defs><path class="grid" d="M30 20H555 M30 65H555 M30 110H555 M30 155H555"/><text x="0" y="24">60</text><text x="0" y="69">40</text><text x="0" y="114">20</text><text x="8" y="159">0</text><path d="M35 112 L120 99 L205 119 L290 88 L375 95 L460 72 L548 47" fill="none" stroke="#c6d2d9" stroke-width="2"/><path d="M35 146 L120 141 L205 144 L290 136 L375 132 L460 127 L548 106 L548 155 L35 155Z" fill="url(#area)"/><path d="M35 146 L120 141 L205 144 L290 136 L375 132 L460 127 L548 106" fill="none" stroke="#16ac91" stroke-width="2.5"/><circle cx="548" cy="106" r="4" fill="#fff" stroke="#16ac91" stroke-width="2"/><path d="M548 22V155" stroke="#dce4e7" stroke-dasharray="3 4"/><rect x="458" y="7" width="88" height="26" rx="5" fill="#eef8f4"/><text x="469" y="24" style="fill:#249981">今日登录 22</text>${['09.08','09.09','09.10','09.11','09.12','09.13','09.14'].map((d,i)=>`<text x="${20+i*85}" y="182">${d}</text>`).join('')}</svg><div class="chart-foot"><i class="dot"></i>虚构历史趋势 · 独立示例序列，非当前反馈样本汇总</div></div>`;}
function sourceBars(){return '<div class="panel-body source-list">'+M.SOURCES.map((s,i)=>{const n=state.feedback.filter(f=>f.source===s).length;return `<div class="source-item"><span class="source-name">${s.replace('TapTap ','')}</span><div class="source-bar"><i style="width:${n/state.feedback.length*100}%"></i></div><small>${n} 条</small></div>`;}).join('')+'</div>';}
function overview(){const m=M.metrics(state),groups=M.clusters(state);return heading('运营总览','今天也从听见玩家开始。这里是反馈、服务与产品改善的共同入口。',button('09.14 · 样例快照','snapshot','calendar')+button('导出情报简报','export','download','primary'))+`<div class="alert-banner">${icon('alert')}<p><strong>登录异常值得优先关注</strong>　${state.feedback.filter(f=>f.group==='login').length} 条样例指向登录问题，${m.urgent} 条 P0 工单待处理。</p>${textButton('查看原文证据 →','cluster','data-group="login"')}</div><div class="metric-grid">${metric('已收集玩家反馈',m.feedback,'条','<span>4 个来源</span> 已完成规则归类','chat')}${metric('待跟进客服工单',m.open,'条',`<span>${m.urgent} 条 P0</span> ${m.overdue} 条超过样例 SLA`,'ticket')}${metric('已关联体验需求',m.demands,'项',`<span>${state.demands.filter(d=>d.status==='待验证').length} 项待验证</span> 从反馈到改善`,'board')}${metric('客服回复质检',qualityAverage(),'分',`<span>${state.tickets.filter(t=>t.quality).length} 条已评</span> 人工四项检查均分`,'check')}</div><div class="columns"><div>${panel('玩家反馈趋势',trend(),'<div class="legend"><span><i></i>登录相关</span><span><i></i>全部反馈</span></div>','最近 7 天 · 演示趋势','bottom-gap')}${panel('优先跟进工单',ticketTable(state.tickets.filter(t=>t.status!=='已解决').slice(0,3)),textButton('全部工单 →','nav','data-page="tickets"'),'按业务紧急程度跟进')}</div><div>${panel('高频问题 TOP 3','<div class="panel-body">'+groups.slice(0,3).map((g,i)=>`<div class="signal-row"><span class="signal-rank">${i+1}</span><div class="signal-main">${textButton(escape(g.title),'cluster',`data-group="${g.id}"`)}<small>${g.category} · ${g.rows.length} 条原文证据</small></div><div class="signal-volume">${g.score}<small>需求评分</small></div></div>`).join('')+'</div>',tag('规则聚类','green'),'样例数 × 影响 × 匹配分 ÷ 工作量','bottom-gap')}${panel('今日行动清单',`<div class="action-list"><div class="action-row"><span class="action-check">${icon('alert')}</span><div><p>复核登录异常并升级处理</p><small>关联 ${state.feedback.filter(f=>f.group==='login').length} 条玩家反馈</small></div>${textButton('去处理','cluster','data-group="login"')}</div><div class="action-row"><span class="action-check">${icon('ai')}</span><div><p>检查客服回复与知识依据</p><small>支付争议应由人工核对</small></div>${textButton('去测试','nav','data-page="ai"')}</div><div class="action-row"><span class="action-check">${icon('board')}</span><div><p>跟进体验优化验证</p><small>记录验证结果，再判断是否完成</small></div>${textButton('查看','nav','data-page="demands"')}</div></div>`,'','','bottom-gap')}${panel('反馈来源分布',sourceBars(),tag('当前样本'))}</div></div><div class="journey"><div class="flow-strip"><strong>一条反馈的旅程</strong><span class="flow-arrow">/</span><span>多渠道收集</span><span class="flow-arrow">→</span><span>人工复核与聚类</span><span class="flow-arrow">→</span><span>客服处理 / 产品需求</span><span class="flow-arrow">→</span><span>效果验证</span></div></div>`;}
function ticketTable(rows){return `<div class="table-wrap"><table><thead><tr><th>工单 / 玩家问题</th><th>优先级</th><th>处理状态</th><th>负责团队</th><th>操作</th></tr></thead><tbody>${rows.map(t=>`<tr><td><button class="text-button cell-title" data-action="ticket" data-id="${t.id}">${escape(t.title)}</button><span class="cell-sub">${t.id} · ${escape(t.user)} ${t.status!=='已解决'&&t.due<'12:00'?' · 超过样例 SLA':''}</span></td><td>${priority(t.priority)}</td><td>${tag(t.status,t.status==='已解决'?'green':t.status==='处理中'?'blue':'amber')}</td><td>${escape(t.assignee)}</td><td>${textButton('处理 →','ticket',`data-id="${t.id}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('没有匹配工单','试试切换状态或清空搜索。')}</div>`;}
function empty(title,description){return `<div class="empty"><strong>${title}</strong><p>${description}</p></div>`;}
function intelligence(){const groups=M.clusters(state);const rows=state.feedback.filter(f=>(filter.source==='全部来源'||f.source===filter.source)&&(filter.group==='all'||f.group===filter.group)&&(!filter.query||(f.text+' '+f.user+' '+f.id).toLowerCase().includes(filter.query.toLowerCase())));return heading('情报中心','把零散的玩家声音，变成有原文依据的需求判断。',button('导出简报','export','download')+button('导入玩家反馈','import','plus','primary'))+`<div class="source-status">${M.SOURCES.map((s,i)=>`<div class="source-tile"><div><strong>${s}</strong><small>样例导入 · ${state.feedback.filter(f=>f.source===s).length} 条</small></div>${icon(['chat','team','ticket','signal'][i])}</div>`).join('')}</div><div class="feedback-grid"><section class="panel"><div class="toolbar"><div class="search-field">${icon('search')}<input class="field" id="feedback-search" placeholder="搜索反馈内容、玩家或编号" value="${escape(filter.query)}" aria-label="搜索玩家反馈"></div><select id="source-filter" class="field" aria-label="来源筛选">${['全部来源',...M.SOURCES].map(s=>`<option ${s===filter.source?'selected':''}>${s}</option>`).join('')}</select><select id="group-filter" class="field" aria-label="问题分类筛选"><option value="all">全部分类</option>${Object.entries(M.GROUPS).map(([id,g])=>`<option value="${id}" ${id===filter.group?'selected':''}>${g.category}</option>`).join('')}</select></div><div class="result-summary">${rows.length} 条匹配反馈 · ${state.lastImport?`上次导入 ${state.lastImport.added} 条，跳过重复 ${state.lastImport.duplicates} 条`:'全部内容均为虚构演示样例'}</div><div class="feedback-list">${rows.map(f=>`<article class="feedback-card"><div class="feedback-meta">${tag(f.source)}<span>${escape(f.user)}</span><span>${f.id}</span><time>${escape(f.time)}</time></div><p class="feedback-text">${escape(f.text)}</p><div class="feedback-bottom">${tag(f.category,f.group==='login'?'amber':'blue')}${f.risk?tag('风险词 · 待人工核验','red'):''}<span class="count-label">规则匹配 ${Math.round(f.confidence*100)}%</span>${textButton(state.tickets.some(t=>t.feedbackId===f.id)?'查看关联工单 →':'转客服工单 →','create-ticket',`data-id="${f.id}"`)}</div></article>`).join('')||empty('没有匹配反馈','换一个关键词或放宽筛选条件。')}</div></section><aside class="panel sticky-panel"><div class="panel-head"><div><h2>需求信号</h2><p>规则聚类 · 所有来源样本的综合排序</p></div>${icon('signal')}</div>${groups.map(g=>`<div class="cluster-card"><div class="row">${priority(g.priority)}<span class="count-label">评分 ${g.score}</span></div><h3>${g.title}</h3><p>${g.reach} 条反馈 · ${new Set(g.rows.map(f=>f.source)).size} 个来源 · 影响系数 ${g.impact}</p><div class="row">${textButton('查看证据','cluster',`data-group="${g.id}"`)}${textButton(state.demands.some(d=>d.group===g.id)?'查看需求 →':'生成需求 →','create-demand',`data-group="${g.id}"`)}</div></div>`).join('')}<div class="panel-body"><div class="notice">匹配分为规则启发值，并非模型置信度。聚类、风险等级与工作量均需人工复核。</div></div></aside></div>`;}
function tickets(){const m=M.metrics(state);const rows=state.tickets.filter(t=>(filter.ticket==='全部'||t.status===filter.ticket)&&(!filter.query||(t.title+' '+t.id+' '+t.user).toLowerCase().includes(filter.query.toLowerCase())));return heading('客服工作台','承接升级事件、协同外包团队，让每个问题有明确的处理记录。',button('查看服务规则','policy','clock')+button('从反馈建单','nav','plus','primary','data-page="intelligence"'))+`<div class="metric-grid">${metric('未解决工单',m.open,'条','待处理、处理中与待回访','ticket')}${metric('高优先级',m.urgent,'条','未解决 P0 工单','alert')}${metric('超过样例 SLA',m.overdue,'条','固定时点 12:00 · 非实时计时','clock')}${metric('已解决',m.resolved,'条','已保存处理说明的完成记录','check')}</div><section class="panel"><div class="toolbar"><div class="filter-tabs">${['全部','待处理','处理中','待回访','已解决'].map(s=>`<button class="filter-tab ${filter.ticket===s?'active':''}" data-action="ticket-filter" data-status="${s}">${s}</button>`).join('')}</div><div class="search-field">${icon('search')}<input class="field" id="ticket-search" value="${escape(filter.query)}" placeholder="搜索工单标题、编号、玩家" aria-label="搜索工单"></div></div>${ticketTable(rows)}</section><div class="notice space-top">处理流程：指定团队 → 保存回复 / 排查记录 → 等待回访 → 确认解决。此处保存的是演示处理记录，不会给玩家发送消息。</div>`;}
function ai(){return heading('AI 客服实验室','管理知识依据，测试回复边界，再交给人工复核。',tag('规则模拟 · 未接入大模型','green'))+`<div class="lab-layout">${panel('知识库',`<div class="panel-body">${M.KB.map(k=>`<article class="knowledge-card"><label><h3>${k.title}</h3><input type="checkbox" data-kb="${k.id}" ${state.kbEnabled.includes(k.id)?'checked':''} aria-label="启用${k.title}"></label><p>${escape(k.text)}</p><span class="count-label">${k.id} · 更新于 ${k.updated}</span></article>`).join('')}<div class="notice">关闭一个知识条目后再测试对应问题，观察回复是否转人工。知识条目为本作品编写的示例规范。</div></div>`,tag(`${state.kbEnabled.length} 条已启用`))}${panel('回复测试台',`<div class="panel-body"><label class="field-label" for="lab-question">玩家问题</label><textarea class="field lab-input" id="lab-question" placeholder="输入问题，测试回复内容、引用依据与转人工策略">${escape(lastAnswer?.question||'更新后一直登录白屏，验证码输入了也进不去，怎么办？')}</textarea><div class="quick-questions">${['登录失败','充值未到账','隐私风险','未知问题'].map((q,i)=>`<button data-action="example" data-example="${i}">${q}</button>`).join('')}</div>${button('生成回复建议','generate-answer','ai','primary')}<span class="count-label">　按启用知识条目匹配</span><div id="answer-result">${lastAnswer?answerHTML(lastAnswer):'<div class="empty"><strong>先试一个真实的问题场景</strong><p>输出包含：回复建议、知识引用和转人工理由。</p></div>'}</div><div class="divider"></div><div class="row"><h3>回归测试</h3>${textButton('运行 4 个测试场景 →','run-eval')}</div><p class="support-note">检查登录知识命中、支付转人工、风险升级、未知问题兜底。测试结果反映当前知识库配置。</p><div id="eval-result"></div></div>`,tag('人工审核后使用','amber'))}</div>`;}
function answerHTML(a){return `<div class="answer-box"><div class="row">${tag(a.human?'建议转人工':'可供人工审核',a.human?'amber':'green')}<span class="count-label">${escape(a.category)}</span></div><p>${escape(a.text)}</p><div class="citations">知识引用：${a.citations.length?a.citations.join('、'):'无匹配知识'}<br>判定依据：${escape(a.reason)}</div></div><div class="answer-controls">${button('复制回复','copy-answer','','small')}${button('存为待处理工单','answer-ticket','','small')}</div>`;}
function demands(){return heading('体验优化看板','反馈有出处，需求有负责人，完成有验证依据。',button('导出需求简报','export','download')+button('从情报生成需求','nav','plus','primary','data-page="intelligence"'))+`<div class="notice bottom-gap">需求评分 = 样例条数 × 影响系数 × 规则匹配分 ÷ 预估工作量。评分辅助讨论，不替代人工判断；“已验证”仅表示完成演示记录。</div><div class="board">${['待评估','方案设计','待验证','已验证'].map(status=>{const items=state.demands.filter(d=>d.status===status);return `<section class="board-column"><div class="board-title">${status}<small>${items.length} 项</small></div>${items.map(d=>{const g=M.clusters(state).find(c=>c.id===d.group);return `<article class="demand-card"><div class="row">${priority(d.priority)}<span class="count-label">${d.id}</span></div><h3>${escape(d.title)}</h3><p>${escape(d.owner)} · ${g?.reach||0} 条原文证据</p>${textButton('查看需求与验证 →','demand',`data-id="${d.id}"`)}<div class="score"><span>需求评分 ${g?.score||0}</span><span>${d.created}</span></div></article>`;}).join('')||'<div class="empty"><p>暂无需求</p></div>'}</section>`;}).join('')}</div><section class="panel space-top"><div class="panel-head"><h2>验证什么，才算改善？</h2>${tag('目标示例，非已有成果')}</div><div class="panel-body policy-grid"><div class="policy"><strong>用户能不能完成任务</strong><p>记录登录成功率、下载完成率或关键任务完成时间。</p></div><div class="policy"><strong>同类问题有没有减少</strong><p>比较优化前后重复咨询率，控制样本量与版本差异。</p></div><div class="policy"><strong>玩家是否认可处理结果</strong><p>通过回访满意度和原文反馈验证，避免仅看工单关闭量。</p></div></div></section>`;}
function qualityAverage(){const items=state.tickets.filter(t=>t.quality);return items.length?Math.round(items.reduce((s,t)=>s+t.quality.score,0)/items.length):'—';}
function team(){return heading('外包团队与质检','用清晰的升级边界与可复核的回复标准，管理服务质量。',button('查看升级规则','policy','ticket'))+`<div class="columns"><div>${panel('团队服务概况',`<div class="table-wrap"><table><thead><tr><th>团队</th><th>待跟进</th><th>已解决</th><th>质检均分</th></tr></thead><tbody>${['一线 A 组','一线 B 组','升级专席'].map(team=>{const items=state.tickets.filter(t=>t.assignee===team),qs=items.filter(t=>t.quality);return `<tr><td><strong>${team}</strong><span class="cell-sub">${team==='升级专席'?'复杂事件与争议核查':'外包客服 · 模拟团队'}</span></td><td>${items.filter(t=>t.status!=='已解决').length}</td><td>${items.filter(t=>t.status==='已解决').length}</td><td>${qs.length?Math.round(qs.reduce((s,t)=>s+t.quality.score,0)/qs.length)+' 分':'待抽检'}</td></tr>`;}).join('')}</tbody></table></div>`,tag('按当前工单实时汇总'),'样例不代表真实团队绩效','bottom-gap')}${panel('回复抽检队列',`<div class="panel-body">${state.tickets.filter(t=>t.reply).map(t=>`<div class="evaluation-row"><span class="evaluation-score">${t.quality?t.quality.score:'—'}</span><div style="flex:1;min-width:0"><h3>${escape(t.title)}</h3><p>${escape(t.reply)}</p><small>${t.id} · ${t.assignee} · ${t.quality?escape(t.quality.note||'已完成四项检查'):'尚未质检'}</small></div>${textButton('抽检 →','quality',`data-id="${t.id}"`)}</div>`).join('')||empty('暂无可抽检回复','先在工单中保存一条回复。')}</div>`,'','每项 25 分 · 人工勾选评分')}</div><div>${panel('服务质量检查表',`<div class="action-list">${['共情：准确回应玩家的困扰','可执行：提供明确下一步','有依据：不编造规则或时效','守边界：保护隐私与升级风险'].map((t,i)=>`<div class="action-row"><span class="action-check">${i+1}</span><div><p>${t}</p><small>符合计 25 分，不符合计 0 分</small></div></div>`).join('')}</div>`,'','','bottom-gap')}${panel('培训闭环',`<div class="panel-body"><p style="font-size:13px">抽检低分回复 → 记录具体缺项 → 更新话术与知识 → 再次抽检。</p><div class="notice space-top">低于 75 分建议复盘；没有已评样本的团队显示“待抽检”。修改回复后会清空旧评分，避免评分与内容脱节。</div></div>`)}</div></div>`;}
function openDialog(title,body,drawer=false){dialog.className=drawer?'drawer':'';dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="关闭对话框">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function showCluster(id){const g=M.clusters(state).find(g=>g.id===id);if(!g){toast('此分类尚无反馈');return;}openDialog(g.title,`<div class="row">${priority(g.priority)}${tag(g.category,'blue')}<span class="count-label">${g.reach} 条反馈 · 评分 ${g.score}</span></div><p class="space-top">${g.summary}</p><dl class="detail-info"><div><dt>影响系数 / 预估工作量</dt><dd>${g.impact} / ${g.effort}（演示估值）</dd></div><div><dt>平均规则匹配分</dt><dd>${Math.round(g.confidence*100)}% · 需人工复核</dd></div></dl><h3>原文证据</h3>${g.rows.map(f=>`<article class="evidence-item"><small>${f.id} · ${f.source} · ${escape(f.user)}</small><p>${escape(f.text)}</p>${textButton(state.tickets.some(t=>t.feedbackId===f.id)?'查看工单':'转客服工单','create-ticket',`data-id="${f.id}"`)}</article>`).join('')}<div class="space-top"><h3>建议产品动作</h3><p>${g.proposal}</p><p class="support-note">${g.target}</p></div><div class="dialog-actions">${button(state.demands.some(d=>d.group===id)?'查看关联需求':'生成产品需求','create-demand','board','primary',`data-group="${id}"`)}</div>`,true);}
function showTicket(id){const t=state.tickets.find(t=>t.id===id);if(!t)return;const f=state.feedback.find(f=>f.id===t.feedbackId);openDialog(`${t.id} · 工单详情`,`<div class="row">${priority(t.priority)}${tag(t.status,'blue')}<span class="count-label">${escape(t.user)} · ${f?.source||'回复测试台'}</span></div><h3 class="space-top">${escape(t.title)}</h3><div class="quote">${escape(t.text)}</div><dl class="detail-info"><div><dt>创建 / SLA 截止（样例时点）</dt><dd>${t.created} / ${t.due}</dd></div><div><dt>关联原文</dt><dd>${t.feedbackId}</dd></div></dl><form id="ticket-form" data-id="${id}"><label class="field-label" for="ticket-owner">负责团队</label><select class="field" id="ticket-owner" name="assignee">${['一线 A 组','一线 B 组','升级专席'].map(s=>`<option ${t.assignee===s?'selected':''}>${s}</option>`).join('')}</select><label class="field-label" for="ticket-status">处理状态</label><select class="field" id="ticket-status" name="status">${['待处理','处理中','待回访','已解决'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select><div class="row" style="justify-content:space-between;margin-bottom:8px"><label class="field-label" for="ticket-reply">处理说明 / 回复草稿</label>${textButton('生成回复建议','ticket-draft',`data-id="${id}"`)}</div><textarea class="field text-area" id="ticket-reply" name="reply" maxlength="4000" placeholder="记录排查结果、下一步和回访安排">${escape(t.reply)}</textarea><div id="ticket-ai-note"></div><div class="notice">仅保存演示记录，不发送给玩家。已解决 / 待回访状态必须填写处理说明。</div><p id="form-error" class="error-message" role="alert"></p><div class="dialog-actions"><button class="button primary" type="submit">保存处理记录</button></div></form><div class="divider"></div><h3>处理轨迹</h3><ol class="history">${t.history.map(h=>`<li>${escape(h)}</li>`).join('')}</ol>`,true);}
function showDemand(id){const d=state.demands.find(d=>d.id===id);if(!d)return;const g=M.GROUPS[d.group],cluster=M.clusters(state).find(c=>c.id===d.group);openDialog(`${d.id} · 体验需求`,`<div class="row">${priority(d.priority)}${tag(d.status,'green')}<span class="count-label">关联 ${cluster?.reach||0} 条反馈</span></div><h3 class="space-top">${escape(d.title)}</h3><p class="support-note">${g.summary}</p><div class="quote">验证指标：${g.metric}<br>${g.target}</div>${textButton('查看全部原文证据 →','cluster',`data-group="${d.group}"`)}<form id="demand-form" data-id="${id}" class="space-top"><label class="field-label" for="demand-owner">需求负责人</label><select class="field" id="demand-owner" name="owner">${['产品 · 林','产品 · 陈','运营 · 韩'].map(o=>`<option ${d.owner===o?'selected':''}>${o}</option>`).join('')}</select><label class="field-label" for="demand-status">推进状态</label><select class="field" id="demand-status" name="status">${['待评估','方案设计','待验证','已验证'].map(s=>`<option ${d.status===s?'selected':''}>${s}</option>`).join('')}</select><label class="field-label" for="demand-note">方案与跟进说明</label><textarea class="field text-area" id="demand-note" name="note" maxlength="4000">${escape(d.note)}</textarea><label class="field-label" for="demand-validation">验证记录（标记已验证时必填）</label><textarea class="field text-area" id="demand-validation" name="validation" maxlength="4000" placeholder="记录样本、方法、观察结果和局限。不要将演示目标写成真实业务成果。">${escape(d.validation)}</textarea><p id="form-error" class="error-message" role="alert"></p><div class="dialog-actions"><button class="button primary" type="submit">保存需求进展</button></div></form><div class="divider"></div><h3>推进记录</h3><ol class="history">${d.history.map(h=>`<li>${escape(h)}</li>`).join('')}</ol>`,true);}
function showImport(){openDialog('导入玩家反馈',`<p class="import-hint">每行一条反馈，最多 100 条，每条最多 2000 字。自动做精确文本去重与关键词归类，内容仅保存在当前浏览器。可直接粘贴下方示例试用。</p><form id="import-form"><label class="field-label" for="import-source">内容来源</label><select class="field" id="import-source" name="source">${M.SOURCES.map(s=>`<option>${s}</option>`).join('')}</select><label class="field-label" for="import-text">玩家原文</label><textarea class="field text-area" id="import-text" name="text" required placeholder="更新后登录一直白屏，试了两次都失败。&#10;充值扣款了但还没到账，麻烦查一下。&#10;希望增加预约游戏的分类筛选。"></textarea>${textButton('填入 3 条示例','import-example')}<p id="form-error" class="error-message" role="alert"></p><div class="dialog-actions"><button class="button primary" type="submit">导入并归类</button></div></form>`);}
function showQuality(id){const t=state.tickets.find(t=>t.id===id);if(!t)return;openDialog(`${id} · 回复质检`,`<h3>${escape(t.title)}</h3><div class="quote">${escape(t.reply)}</div><form id="quality-form" data-id="${id}"><div class="quality-form">${['回应玩家困扰，表达适当共情','提供清晰、可执行的下一步','与知识依据一致，不编造结果或时效','保护隐私，遵守转人工与风险边界'].map((s,i)=>`<label><input type="checkbox" name="q${i}" ${t.quality?.checks[i]?'checked':''}>${s}（25 分）</label>`).join('')}</div><label class="field-label" for="quality-note">质检备注 / 培训建议</label><textarea id="quality-note" class="field text-area" name="note" maxlength="2000" placeholder="请指出具体缺项，作为团队复盘依据">${escape(t.quality?.note||'')}</textarea><div class="dialog-actions"><button class="button primary" type="submit">保存质检结果</button></div></form>`);}
function showTour(){openDialog('建议演示路线 · 约 3 分钟',`<p class="import-hint">用“登录异常”讲清楚你怎样把玩家反馈变成系统改进。</p>${[['1','看见问题','在情报中心查看登录聚类，核对来源与原文。','intelligence'],['2','接住玩家','创建关联工单，生成回复草稿并指派升级专席。','tickets'],['3','解决一类问题','将登录聚类生成需求，补充负责人和验证指标。','demands'],['4','让服务持续改善','测试知识库开关与转人工策略，再抽检回复质量。','ai']].map(([n,t,p,page])=>`<div class="tour-step"><b>${n}</b><div><h3>${t}</h3><p>${p}</p></div>${textButton('打开 →','tour-nav',`data-page="${page}"`)}</div>`).join('')}<div class="notice space-top">可运行：筛选、导入去重、建单、分派、质检、知识匹配、需求流转和简报导出。未接入：真实平台、定时采集、大模型、消息发送及生产监控。</div>`);}
function showPolicy(){openDialog('服务与升级规则（演示）',`<div class="policy-grid"><div class="policy"><strong>P0 · 优先升级</strong><p>集中登录故障、支付争议与风险事件。演示 SLA：2 小时。</p></div><div class="policy"><strong>P1 · 常规处理</strong><p>下载、社区问题。演示 SLA：4 小时。</p></div><div class="policy"><strong>P2 · 需求研判</strong><p>建议和未分类问题。人工补充场景后评估。</p></div></div><div class="divider"></div><p>一线团队负责收集事实、说明操作步骤与记录问题。升级专席负责复杂故障、支付争议和高风险问题。涉及资金、隐私或无法找到知识依据时，不由规则引擎自动定责或承诺结果。</p><div class="notice space-top">样例时钟固定在 2026.09.14 12:00，SLA 只用于说明队列排序和升级思路。正式系统需由服务端统一计时并接入告警。</div>`);}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,group=el.dataset.group;try{switch(a){
case 'nav':if(el.dataset.page!==current)filter.query='';navigate(el.dataset.page);break;
case 'close':dialog.close();break;
case 'snapshot':showPolicy();break;
case 'tour':showTour();break;
case 'tour-nav':dialog.close();filter.query='';navigate(el.dataset.page);break;
case 'help':openDialog('关于这个作品',`<p>这是韩家豪面向 TapTap 产品运营岗位制作的独立交互作品，覆盖客服系统运营、反馈情报建设和体验优化跟进。</p><div class="divider"></div><p>所有初始玩家、工单、团队、业务指标均为虚构。AI 建议使用本地关键词和知识模板生成；没有实际接入大模型、爬虫或 TapTap 系统。</p><p class="space-top">操作${storageOK?'保存在当前浏览器，可刷新继续演示':'暂存在当前页面，浏览器存储不可用'}。导出简报会包含当前导入内容。演示中标记“已解决”或“已验证”不会触发任何真实业务操作。</p><div class="dialog-actions">${button('重置演示数据','reset','','danger')}${button('查看演示路线','tour','','primary')}</div>`);break;
case 'policy':showPolicy();break;
case 'import':showImport();break;
case 'import-example':document.getElementById('import-text').value='更新后登录一直白屏，试了两次都失败。\n充值扣款了但还没到账，麻烦查一下。\n希望增加预约游戏的分类筛选。';break;
case 'cluster':showCluster(group);break;
case 'ticket':showTicket(id);break;
case 'create-ticket':{const r=M.makeTicket(state,id);save();render();showTicket(r.ticket.id);toast(r.existing?'已打开关联工单，未重复建单':'已从原文创建工单');break;}
case 'create-demand':{const r=M.makeDemand(state,group);save();render();showDemand(r.demand.id);toast(r.existing?'已打开同类需求，未重复创建':'已关联原文并生成需求');break;}
case 'demand':showDemand(id);break;
case 'ticket-filter':filter.ticket=el.dataset.status;render();break;
case 'ticket-draft':{const t=state.tickets.find(t=>t.id===id);const ans=M.draftAnswer(state,t.text);document.getElementById('ticket-reply').value=ans.text;document.getElementById('ticket-ai-note').innerHTML=`<div class="notice" style="margin-bottom:15px">规则建议 · ${ans.human?'建议转人工':'请人工复核'} · 引用：${ans.citations.join('、')||'无'}。草稿尚未保存。</div>`;break;}
case 'example':document.getElementById('lab-question').value=['更新后登录白屏，验证码输入了也进不去。','充值扣款成功但道具还没有到账。','有人在评论里公开我的手机号，存在隐私泄露。','你们明天的天气会怎么样？'][Number(el.dataset.example)];break;
case 'generate-answer':{const q=document.getElementById('lab-question').value.trim();lastAnswer={...M.draftAnswer(state,q),question:q};document.getElementById('answer-result').innerHTML=answerHTML(lastAnswer);break;}
case 'copy-answer':if(lastAnswer){try{await navigator.clipboard.writeText(lastAnswer.text);toast('回复已复制');}catch{openDialog('复制回复',`<p class="import-hint">浏览器未允许自动复制，可选择下方文本复制。</p><textarea class="field text-area" readonly>${escape(lastAnswer.text)}</textarea>`);}}break;
case 'answer-ticket':if(lastAnswer){M.importFeedback(state,lastAnswer.question,'客服工单');const f=state.feedback.find(f=>f.text.trim().replace(/\s+/g,' ').toLowerCase()===lastAnswer.question.trim().replace(/\s+/g,' ').toLowerCase());const r=M.makeTicket(state,f.id);save();render();showTicket(r.ticket.id);toast('已关联测试问题，回复需审核后保存');}break;
case 'run-eval':{const results=[['登录知识匹配','登录白屏验证码失败',a=>a.citations.includes('KB-001')],['支付必须转人工','充值未到账',a=>a.human],['隐私风险升级','评论泄露隐私',a=>a.human&&!a.citations.length],['未知问题兜底','明天天气怎么样',a=>a.human&&!a.citations.length]].map(([title,q,assert])=>{const ans=M.draftAnswer(state,q);return {title,passed:assert(ans)};});document.getElementById('eval-result').innerHTML=`<div class="space-top">${results.map(r=>`<div class="row" style="justify-content:space-between;margin-top:8px"><span>${r.title}</span>${tag(r.passed?'通过':'未通过，请检查知识配置',r.passed?'green':'amber')}</div>`).join('')}</div>`;break;}
case 'quality':showQuality(id);break;
case 'export':{const blob=new Blob([M.report(state)],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='玩家信号_情报与需求简报.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已导出当前反馈与需求简报');break;}
case 'reset':openDialog('重置本地演示数据',`<p>这会清除当前浏览器中的导入反馈、工单修改、质检和需求进展，恢复初始样例。可先导出简报留存。</p><div class="dialog-actions">${button('先导出简报','export','download')}${button('取消','close')}${button('确认重置','confirm-reset','','danger')}</div>`);break;
case 'confirm-reset':state=M.seed();filter={query:'',source:'全部来源',group:'all',ticket:'全部'};lastAnswer=null;save();dialog.close();navigate('overview');toast('已恢复初始演示数据，原本地修改不可恢复');break;
}}catch(error){toast(error.message||'操作未完成，请重试');}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='source-filter'){filter.source=el.value;render();}if(el.id==='group-filter'){filter.group=el.value;render();}if(el.dataset.kb){if(el.checked&&!state.kbEnabled.includes(el.dataset.kb))state.kbEnabled.push(el.dataset.kb);else if(!el.checked)state.kbEnabled=state.kbEnabled.filter(id=>id!==el.dataset.kb);save();lastAnswer=null;render();toast('知识配置已更新，请重新测试回复');}});
document.addEventListener('input',event=>{if(['feedback-search','ticket-search'].includes(event.target.id)){const id=event.target.id,pos=event.target.selectionStart;filter.query=event.target.value;render();const el=document.getElementById(id);el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('submit',event=>{const form=event.target;if(!['import-form','ticket-form','demand-form','quality-form'].includes(form.id))return;event.preventDefault();const fd=new FormData(form);try{if(form.id==='import-form'){const result=M.importFeedback(state,fd.get('text'),fd.get('source'));save();dialog.close();filter={query:'',source:'全部来源',group:'all',ticket:'全部'};navigate('intelligence');toast(`导入 ${result.added} 条，跳过重复 ${result.duplicates} 条`);}else if(form.id==='ticket-form'){M.updateTicket(state,form.dataset.id,{status:fd.get('status'),assignee:fd.get('assignee'),reply:fd.get('reply')});save();dialog.close();render();toast('工单处理记录已保存');}else if(form.id==='demand-form'){const d=state.demands.find(d=>d.id===form.dataset.id),status=fd.get('status'),validation=fd.get('validation').trim();if(status==='已验证'&&!validation)throw new Error('请填写验证方法与观察结果，再标记已验证');if(!['待评估','方案设计','待验证','已验证'].includes(status))throw new Error('无效需求状态');d.status=status;d.owner=fd.get('owner');d.note=fd.get('note').trim();d.validation=validation;d.history.push('演示操作：'+d.owner+' · '+status+(validation?' · 更新验证记录':''));save();dialog.close();render();toast('需求进展已保存');}else{const t=state.tickets.find(t=>t.id===form.dataset.id);const checks=[0,1,2,3].map(i=>fd.has('q'+i));t.quality={checks,score:checks.filter(Boolean).length*25,note:fd.get('note').trim()};save();dialog.close();render();toast(`质检已保存：${t.quality.score} 分`);}}catch(error){const el=form.querySelector('#form-error');if(el)el.textContent=error.message;else toast(error.message);}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
navigate(location.hash.slice(1)||'overview');
if(document.modelContext?.registerTool){const controller=new AbortController();for(const tool of [{name:'read_feedback_clusters',title:'读取玩家反馈聚类',description:'读取当前演示数据的反馈聚类和需求评分，不更改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('输入应为空对象');return M.clusters(state).map(g=>({group:g.id,title:g.title,count:g.reach,score:g.score}));}},{name:'create_demo_demand',title:'创建演示体验需求',description:'从当前反馈分类创建本地演示需求并打开详情；重复调用返回已有关联需求。不会写入真实业务系统。',inputSchema:{type:'object',properties:{group:{type:'string',enum:Object.keys(M.GROUPS)}},required:['group'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.group!=='string'||Object.keys(input).some(k=>k!=='group')||!Object.hasOwn(M.GROUPS,input.group)||!state.feedback.some(f=>f.group===input.group))throw new Error('请选择有反馈的有效分类');const result=M.makeDemand(state,input.group);save();render();showDemand(result.demand.id);return {id:result.demand.id,status:result.demand.status,existing:result.existing};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
